// Walks backward counting paren depth (a naive `\(([^()]*)\)` regex fails since markdown links themselves contain `()`).
function matchingOpenParen(s, end) {
    let depth = 1;
    for (let i = end - 2; i >= 0; i--) {
        const c = s[i];
        if (c === ")") {
            depth++;
            continue;
        }
        if (c !== "(") {
            continue;
        }
        depth--;
        if (depth === 0) {
