    const label = match[1].replace(/\s+/g, " ").trim();
    const href = match[2].trim();
    const hashIdx = href.indexOf("#L");
    const rawPath = hashIdx >= 0 ? href.slice(0, hashIdx) : href;
    const path = rawPath.replace(/^\/+/, "");
    let line = null;
