        return [];
    }
    const inner = statement.slice(span.innerStart, span.innerEnd);
    const refs = [];
    for (const match of inner.matchAll(LINK_INSIDE_PAREN_RE)) {
        const ref = linkRefFromMatch(match);
        if (keepPath(ref.path)) {
            refs.push(ref);
        }
    }
    return refs;
