Careful: `re-lint/max-comment-lines` — comments at most one line, including JSDoc. So every comment must be a single line. And `re-lint/require-spec-link` — every test must be cited from a spec. My spec edit provides that.

The test:

```ts
const SENT_AT = '2026-01-01T00:00:00.000Z';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

// A provider that fails the turn if the orchestrator ever reaches it.
const unreachableProvider = (): AIProvider => ({
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw new Error('the provider must not be reached');
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('beforeSession failure (HALEngine#94)', () => {
  it('runs onError then afterSession when it throws, and still rejects to the caller', async () => {
    const thrown = new Error('beforeSession failed');
    const callOrder: string[] = [];
    let receivedSessionId: string | number | undefined;
    let receivedErrorMessage: string | undefined;

    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        callOrder.push('beforeSession');
        throw thrown;
      },
      beforeUserInput: async (_session, userMessage) => {
        callOrder.push('beforeUserInput');
        return userMessage;
      },
      afterUserInput: async () => void callOrder.push('afterUserInput'),
      beforeModelResponse: async (_session, systemPrompt) => {
        callOrder.push('beforeModelResponse');
        return systemPrompt;
      },
      afterModelResponse: async () => void callOrder.push('afterModelResponse'),
      onError: async (session, error) => {
        callOrder.push('onError');
        receivedSessionId = session.sessionId;
        receivedErrorMessage = error.message;
      },
      afterSession: async () => void callOrder.push('afterSession'),
    };

    const orchestrator = createChatOrchestrator(unreachableProvider(), promptBuilder, undefined, {hooks});

    const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

    expect({outcome, receivedSessionId, receivedErrorMessage, callOrder}).toEqual({
      outcome: 'beforeSession failed',
      receivedSessionId: 's1',
      receivedErrorMessage: 'beforeSession failed',
      callOrder: ['beforeSession', 'onError', 'afterSession'],
    });
  });
});
```

